    "Game update: {gameVersion} · Menu version: {menuVersion} · BIN · GamerHack 900v3 build · {titleIds}": "Aktualizacja gry: {gameVersion} · Wersja menu: {menuVersion} · BIN · Kompilacja hosta GamerHack 900v3 · {titleIds}",
    "Game update: {gameVersion} · Menu version: Not provided · BIN · GamerHack 900v3 build · {titleIds}": "Aktualizacja gry: {gameVersion} · Wersja menu: Nie podano · BIN · Kompilacja hosta GamerHack 900v3 · {titleIds}",
